**已修复代码：**

```diff
-import type {Token} from './token-service.ts';
+import type {Token} from '../../..//src/auth/token-service.ts';

-export function refresh(current:Token,next:Token){return current;}
+export function refresh(current:Token,next:Token){return next;}

-export function canLogin(attempts:number){return attempts<3;}
-export const LOGIN_LIMIT = 3;
```

**检查命令：**

```bash
node tests/check.mjs scenario 'auth-refresh'
node tests/check.mjs scenario 'all'
```

